CREATE SCHEMA ol_warehouse_production_dimensional;
CREATE SCHEMA ol_warehouse_production_intermediate;
CREATE TABLE ol_warehouse_production_dimensional.tfact_discussion_events (platform VARCHAR, courserun_readable_id VARCHAR, event_type VARCHAR, post_title VARCHAR, post_content VARCHAR, discussion_component_name VARCHAR, page_url VARCHAR, event_timestamp TIMESTAMP);
