CREATE TABLE ol_warehouse_production_intermediate.int__combined__course_runs (courserun_readable_id VARCHAR, platform VARCHAR, course_title VARCHAR);
INSERT INTO ol_warehouse_production_intermediate.int__combined__course_runs VALUES ('1', 'MITx Online', 'Sample course'), ('2', 'mitxonline', 'Second course');
CREATE TABLE ol_warehouse_production_dimensional.dim_course_run (courserun_readable_id VARCHAR, platform VARCHAR, courserun_title VARCHAR, course_fk INTEGER, effective_date DATE, is_current BOOLEAN);
INSERT INTO ol_warehouse_production_dimensional.dim_course_run VALUES ('1', 'mitxonline', 'Sample run', 101, DATE '2024-01-01', TRUE), ('2', 'mitxonline', 'Second run', 102, DATE '2024-01-01', TRUE);
CREATE TABLE ol_warehouse_production_dimensional.dim_course (course_pk INTEGER, course_title VARCHAR, effective_date DATE, is_current BOOLEAN);
INSERT INTO ol_warehouse_production_dimensional.dim_course VALUES (101, 'Sample course', DATE '2024-01-01', TRUE);
CREATE VIEW course_titles AS
select courserun_readable_id, platform, course_title
from (
    select
        dcr.courserun_readable_id,
        dcr.platform,
        coalesce(dc.course_title, dcr.courserun_title) as course_title,
        row_number() over (
            partition by dcr.platform, dcr.courserun_readable_id
            order by dcr.effective_date desc nulls last, dc.effective_date desc nulls last
        ) as _row_num
    from ol_warehouse_production_dimensional.dim_course_run as dcr
    left join ol_warehouse_production_dimensional.dim_course as dc
        on dcr.course_fk = dc.course_pk
        and dc.is_current = true
    where dcr.is_current = true
)
where _row_num = 1;
